CREATE TABLE service_queues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),UNIQUE(tenant_id,id),UNIQUE(tenant_id,unit_id,code));
INSERT INTO service_queues(tenant_id,unit_id,code,name) SELECT u.tenant_id,u.id,q.code,q.name FROM units u CROSS JOIN (VALUES('recepcao','Recepção'),('agenda','Agendamento'),('convenios','Documentos e convênios'),('clinica','Coordenação clínica'),('auditoria','Auditoria'),('financeiro','Financeiro')) AS q(code,name) ON CONFLICT DO NOTHING;
ALTER TABLE conversations ADD COLUMN queue_id uuid,ADD COLUMN assigned_user_id uuid,ADD COLUMN recommended_professional_id uuid,ADD COLUMN ai_mode text NOT NULL DEFAULT 'HUMAN' CHECK(ai_mode IN('AI','HUMAN')),ADD COLUMN sandbox boolean NOT NULL DEFAULT false,ADD COLUMN include_clinical_context boolean NOT NULL DEFAULT false,ADD COLUMN consent_at timestamptz,ADD COLUMN automation_epoch int NOT NULL DEFAULT 1;
ALTER TABLE conversations ADD FOREIGN KEY(tenant_id,queue_id) REFERENCES service_queues(tenant_id,id),ADD FOREIGN KEY(assigned_user_id) REFERENCES users(id),ADD FOREIGN KEY(tenant_id,recommended_professional_id) REFERENCES professionals(tenant_id,id);
ALTER TABLE ledger ADD COLUMN counterparty_ref text;
ALTER TABLE conversations ADD COLUMN context_started_at timestamptz;
ALTER TABLE payment_events ADD COLUMN counterparty_ref text;
CREATE TABLE sandbox_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,conversation_id uuid NOT NULL,name text NOT NULL,mime text NOT NULL CHECK(mime IN('application/pdf','image/png','image/jpeg','image/webp')),content bytea NOT NULL,sha256 text NOT NULL,page_count int,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(octet_length(content)<=2097152),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),UNIQUE(tenant_id,id));
ALTER TABLE messages ADD COLUMN request_id uuid,ADD COLUMN agent_run_id uuid,ADD COLUMN agent_name text;
CREATE UNIQUE INDEX messages_idempotency ON messages(tenant_id,conversation_id,request_id) WHERE request_id IS NOT NULL;
CREATE UNIQUE INDEX messages_run_response ON messages(tenant_id,agent_run_id) WHERE agent_run_id IS NOT NULL;
CREATE TABLE message_attachments(tenant_id uuid NOT NULL,message_id uuid NOT NULL REFERENCES messages(id),attachment_id uuid NOT NULL,FOREIGN KEY(tenant_id,attachment_id) REFERENCES sandbox_attachments(tenant_id,id),PRIMARY KEY(message_id,attachment_id));
CREATE TABLE agent_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,conversation_id uuid NOT NULL,input_message_id uuid NOT NULL REFERENCES messages(id),requested_by uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')),provider text NOT NULL,model text NOT NULL,agent_snapshot jsonb NOT NULL,decision jsonb,trace jsonb NOT NULL DEFAULT '[]',input_tokens int NOT NULL DEFAULT 0,output_tokens int NOT NULL DEFAULT 0,attempts int NOT NULL DEFAULT 0,lease_id uuid,automation_epoch int NOT NULL,error_code text,error_message text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX one_active_agent_run ON agent_runs(tenant_id,conversation_id) WHERE status IN('QUEUED','RUNNING');
CREATE INDEX agent_jobs ON agent_runs(status,created_at);
ALTER TABLE messages ADD FOREIGN KEY(tenant_id,agent_run_id) REFERENCES agent_runs(tenant_id,id);
CREATE TABLE worker_heartbeats(id uuid PRIMARY KEY,last_seen timestamptz NOT NULL);
CREATE TABLE sandbox_requests(tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,request_id uuid NOT NULL,run_id uuid NOT NULL,FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,run_id) REFERENCES agent_runs(tenant_id,id),PRIMARY KEY(tenant_id,conversation_id,request_id));
